CREATE TABLE payment_settlement_accounts (id UUID PRIMARY KEY, provider VARCHAR(20) NOT NULL, currency_code VARCHAR(3) NOT NULL, ledger_account_id UUID NOT NULL REFERENCES ledger_accounts(id), created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_payment_settlement_provider_currency UNIQUE (provider, currency_code), CONSTRAINT uq_payment_settlement_ledger_account UNIQUE (ledger_account_id));